    'display.marginMaxWidthSummary': ["邊距 · 最大寬度","Margin · Maximum Width","余白・最大幅","여백 · 최대 너비","边距 · 最大宽度"],
    'display.paddingXLabel': ["左右邊距","Left/right padding","左右の余白","좌우 여백","左右边距"],
